import { test } from "node:test";
import assert from "node:assert/strict";
import { NotRefundableError, RefundService } from "../src/tickets/refunds.ts";
import { previewRefund } from "../src/tickets/preview.ts";
import type { EventInfo, Ticket, TicketStore } from "../src/tickets/types.ts";

const SHOW = new Date("2026-12-20T20:00:00Z");
const before = (hours: number) => new Date(SHOW.getTime() - hours * 3_600_000);

function setup(status: EventInfo["status"] = "scheduled") {
    const event: EventInfo = { id: "e1", name: "Fado night", startsAt: SHOW, status };
    const tickets = new Map<string, Ticket>();
    const add = (id: string, tier: Ticket["tier"], priceCents: number, holderId = "maria") =>
        tickets.set(id, { id, eventId: "e1", holderId, tier, priceCents, bookingFeeCents: 300, paymentId: `pay-${id}`, refundedCents: null });
    add("std", "standard", 4000);
    add("flex", "flex", 5500);
    const store: TicketStore = {
        ticket: async (id) => tickets.get(id) ?? null,
        event: async (id) => (id === event.id ? event : null),
        saveTicket: async (t) => void tickets.set(t.id, t),
    };
    const paid: [string, number][] = [];
    const service = new RefundService(store, { refund: async (paymentId, cents) => void paid.push([paymentId, cents]) });
    return { store, tickets, paid, service, add };
}

test("a standard ticket returned two weeks out is refunded in full, without the booking fee", async () => {
    const { service, paid } = setup();
    const t = await service.refund("std", "maria", before(20 * 24));
    assert.equal(t.refundedCents, 4000);
    assert.deepEqual(paid, [["pay-std", 4000]]);
});

test("a standard ticket gets half back inside 14 days and nothing inside 72 hours", async () => {
    const { service, add } = setup();
    assert.equal((await service.refund("std", "maria", before(5 * 24))).refundedCents, 2000);
    add("std2", "standard", 4000);
    await assert.rejects(service.refund("std2", "maria", before(48)), NotRefundableError);
});

test("a flex ticket returned two days before the show is refunded what the preview promised", async () => {
    const { service, store } = setup();
    const preview = await previewRefund(store, "flex", before(48));
    const result = await service.refund("flex", "maria", before(48)).catch((err: Error) => err.message);
    console.log("preview:", preview.message, "| refund:", result);
    assert.equal(preview.amountCents, 5500);
    assert.equal(typeof result === "string" ? result : result.refundedCents, 5500);
});

test("a flex ticket returned on the day still gets half back", async () => {
    const { service, paid } = setup();
    await service.refund("flex", "maria", before(10));
    assert.deepEqual(paid, [["pay-flex", 2750]]);
});

test("no ticket can be returned once the show has started", async () => {
    const { service, store } = setup();
    assert.equal((await previewRefund(store, "flex", before(-1))).refundable, false);
    await assert.rejects(service.refund("flex", "maria", before(-1)), /outside the refund window/);
});

test("when the organiser cancels, every unrefunded ticket gets its price and booking fee back", async () => {
    const { service, tickets, paid } = setup("cancelled");
    tickets.set("old", { ...tickets.get("std")!, id: "old", paymentId: "pay-old", refundedCents: 4000 });
    const total = await service.refundCancelledEvent([...tickets.values()], before(2));
    assert.equal(total, 4300 + 5800);
    assert.deepEqual(paid.map(([id]) => id).sort(), ["pay-flex", "pay-std"]);
});

test("a ticket can't be refunded twice or by someone who doesn't hold it", async () => {
    const { service, store } = setup();
    await assert.rejects(service.refund("std", "joao", before(20 * 24)), /not your ticket/);
    await service.refund("std", "maria", before(20 * 24));
    await assert.rejects(service.refund("std", "maria", before(20 * 24)), /already refunded/);
    assert.equal((await previewRefund(store, "std", before(20 * 24))).message, "Already refunded €40.00");
});

test("the amount refunded always matches the preview, for every tier and time", async () => {
    const mismatches: string[] = [];
    for (const id of ["std", "flex"]) {
        for (const hours of [400, 300, 100, 60, 25, 23, 1]) {
            const { service, store } = setup();
            const preview = await previewRefund(store, id, before(hours));
            const got = await service.refund(id, "maria", before(hours)).then((t) => t.refundedCents, () => 0);
            if (got !== preview.amountCents) mismatches.push(`${id} ${hours}h: preview ${preview.amountCents}, refunded ${got}`);
        }
    }
    assert.deepEqual(mismatches, []);
});
